package com.yeyamo_mobile.api.user_service.infrastructure.messaging;
import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.user_service.application.UserProfileService;
class UserCreatedEventConsumerTests{@Test void createsProfileFromAuthContractOnce()throws Exception{UserProfileService profiles=mock(UserProfileService.class);ProcessedEventRepository processed=mock(ProcessedEventRepository.class);when(processed.existsById(any())).thenReturn(false);String event="{\"eventId\":\"22222222-2222-2222-2222-222222222222\",\"eventType\":\"user.created\",\"correlationId\":\"req-2\",\"payload\":{\"userId\":\"42\",\"email\":\"alice@yeyamo.test\"}}";new UserCreatedEventConsumer(new ObjectMapper(),profiles,processed).consume(event);verify(profiles).createFromIdentity("42","alice@yeyamo.test","req-2");verify(processed).save(any(ProcessedEventEntity.class));}}
